const EventEmitter = require("events");

class Caisse extends EventEmitter {
  constructor(seuil) {
    super();
    this.seuil = seuil;
    this.total = 0;
  }

  vendre(montant) {
    this.total += montant;
    this.emit("vente", montant);
    if (this.total >= this.seuil && this.total - montant < this.seuil) {
      this.emit("objectif", this.total);
    }
  }
}

